import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be positive")
    system = platform.system().lower()
    def get_cpu_usage():
        if "windows" in system:
            try:
                result = subprocess.check_output(
                    ["wmic", "cpu", "get", "loadpercentage", "/value"],
                    stderr=subprocess.DEVNULL
                ).decode().strip().splitlines()
                for line in result:
                    if line.lower().startswith("loadpercentage"):
                        _, value = line.split("=", 1)
                        return float(value.strip())
            except Exception:
                return None
        else:
            try:
                try:
                    result = subprocess.check_output(
                        ["mpstat", "1", "1"],
                        stderr=subprocess.DEVNULL
                    ).decode().splitlines()
                    for line in reversed(result):
                        if "%idle" in line.lower():
                            continue
                        parts = line.split()
                        if len(parts) > 3:
                            idle = float(parts[-1])
                            return 100.0 - idle
                except Exception:
                    result = subprocess.check_output(
                        ["top", "-bn1"],
                        stderr=subprocess.DEVNULL
                    ).decode().splitlines()
                    for line in result:
                        if "Cpu(s)" in line or "Cpu(s):" in line:
                            text = line.replace(",", ".")
                            if " id" in text:
                                part = text.split(" id")[0].split()[-1]
                                idle = float(part)
                                return 100.0 - idle
            except Exception:
                return None
        return None
    logs = []
    start_time = time.time()
    while True:
        now = time.time()
        if now - start_time > duration:
            break
        usage = get_cpu_usage()
        logs.append({"timestamp": now, "cpu_usage": usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as f:
            json.dump(logs, f)
        return LOGFILE_PATH
    except OSError:
        return None

