import subprocess
import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not os.path.isfile(script_path):
        raise FileNotFoundError(f"No such file: '{script_path}'")

    process_container = {"proc": None}
    result_container = {"code": None}

    def run_script():
        proc = subprocess.Popen(["python", script_path])
        process_container["proc"] = proc
        result_container["code"] = proc.wait()

    thread = threading.Thread(target=run_script)
    thread.start()
    thread.join(timeout)

    proc = process_container["proc"]

    if thread.is_alive():
        if proc is not None:
            proc.terminate()
            try:
                proc.wait(timeout=5)
            except Exception:
                pass
        return "Terminating process due to timeout."
    else:
        return "Script executed successfully."

