from datetime import datetime
def task_func(script_name='backup.sh', log_file='/home/user/backup_log.json'):
    script_path = script_name
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")
    start_time_dt = datetime.now()
    start_time = start_time_dt.strftime('%Y-%m-%d %H:%M:%S')
    try:
        completed = subprocess.run(script_path, shell=True)
    except (OSError, subprocess.SubprocessError) as e:
        raise RuntimeError(f"Error executing script: {e}")
    end_time_dt = datetime.now()
    end_time = end_time_dt.strftime('%Y-%m-%d %H:%M:%S')
    result = {
        'start_time': start_time,
        'end_time': end_time,
        'exit_status': completed.returncode
    }
    logs = []
    if os.path.exists(log_file):
        try:
            with open(log_file, 'r') as f:
                existing = json.load(f)
                if isinstance(existing, list):
                    logs = existing
                elif isinstance(existing, dict):
                    logs = [existing]
        except (json.JSONDecodeError, OSError):
            logs = []
    logs.append(result)
    with open(log_file, 'w') as f:
        json.dump(logs, f)
    return result

import subprocess
import shutil
import os
import sys
def task_func(script_path: str, temp_dir: str) -> str:
    if not isinstance(script_path, str) or not isinstance(temp_dir, str):
        raise TypeError("script_path and temp_dir must be strings")
    if not os.path.isfile(script_path):
        return "Script execution failed!"
    if os.path.exists(temp_dir):
        try:
            shutil.rmtree(temp_dir)
        except Exception:
            return "Script execution failed!"
    try:
        os.makedirs(temp_dir, exist_ok=True)
    except Exception:
        return "Script execution failed!"
    try:
        script_name = os.path.basename(script_path)
        temp_script_path = os.path.join(temp_dir, script_name)
        shutil.copy(script_path, temp_script_path)
    except Exception:
        return "Script execution failed!"
    try:
        result = subprocess.run(
            [sys.executable, temp_script_path],
            cwd=temp_dir,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        )
        if result.returncode == 0:
            return "Script executed successfully!"
        else:
            return "Script execution failed!"
    except Exception:
        return "Script execution failed!"

