import random
import os
def task_func(file):
    try:
        if not isinstance(file, str):
            return []
        if not os.path.isfile(file):
            return []
        if os.path.splitext(file)[1].lower() != '.csv':
            return []
        directory = os.path.dirname(os.path.abspath(file))
        prefix = os.path.join(directory, 'split_')
        try:
            subprocess.run(['split', '-l', '1000', file, prefix], check=True)
        except Exception:
            return []
        split_files = sorted(glob.glob(prefix + '*'))
        if not split_files:
            return []
        for path in split_files:
            try:
                with open(path, newline='', encoding='utf-8') as f:
                    reader = csv.reader(f)
                    rows = list(reader)
                random.shuffle(rows)
                with open(path, 'w', newline='', encoding='utf-8') as f:
                    writer = csv.writer(f)
                    writer.writerows(rows)
            except Exception:
                return []
        return split_files
    except Exception:
        return []

import subprocess
import psutil
import time
def task_func(process_name: str) -> str:
    running = False
    pid_to_kill = None
    for proc in psutil.process_iter(attrs=["name"]):
        try:
            if proc.info.get("name") == process_name:
                running = True
                pid_to_kill = proc.pid
                break
        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
            continue
    if not running:
        subprocess.Popen(process_name)
        time.sleep(0.5)
        return f"Process not found. Starting {process_name}."
    else:
        try:
            proc = psutil.Process(pid_to_kill)
            proc.terminate()
        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
            pass
        time.sleep(0.5)
        subprocess.Popen(process_name)
        time.sleep(0.5)
        return f"Process found. Restarting {process_name}."

