def task_func(test_dir):
    if not isinstance(test_dir, str):
        raise TypeError("test_dir must be a string")
    norm_dir = os.path.normpath(test_dir)
    if not os.path.isdir(norm_dir):
        raise OSError("Invalid directory")
    pattern = os.path.join(norm_dir, "*.py")
    scripts = glob.glob(pattern)
    results = {}
    for script in scripts:
        start = time.time()
        try:
            subprocess.run([sys.executable, script], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except Exception:
            pass
        end = time.time()
        script_name = os.path.basename(script)
        results[script_name] = end - start
    return results

