    return version_str

import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    src_folder = os.path.abspath(src_folder)
    dst_folder = os.path.abspath(dst_folder)
    os.makedirs(dst_folder, exist_ok=True)
    all_paths = glob(os.path.join(src_folder, '*'))
    files = [p for p in all_paths if os.path.isfile(p)]
    failed_files = []
    if not files:
        return {
            'success': False,
            'message': 'No files found to compress in the source folder.',
            'failed_files': failed_files
        }
    for file_path in files:
        try:
            proc = subprocess.Popen(['gzip', file_path])
            proc.wait()
            if proc.returncode != 0:
                failed_files.append(os.path.basename(file_path))
                continue
            gz_path = file_path + '.gz'
            try:
                shutil.move(gz_path, dst_folder)
            except Exception:
                failed_files.append(os.path.basename(gz_path))
        except Exception:
            failed_files.append(os.path.basename(file_path))
    total = len(files)
    failed_count = len(failed_files)
    success = failed_count == 0
    if success:
        message = f'All {total} files were compressed and moved successfully.'
    else:
        if failed_count == total:
            message = 'All files failed to compress or move.'
        else:
            message = f'{total - failed_count} of {total} files were compressed and moved successfully; {failed_count} failed.'
    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }

import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not script_path or not os.path.isfile(script_path):
        raise FileNotFoundError("Script path does not exist")
    start_time = time.time()
    proc = subprocess.Popen(['/bin/bash', script_path])
    p = psutil.Process(proc.pid)
    cpu_usage = 0.0
    mem_usage = 0
    last_rss = 0
    try:
        while True:
            if time.time() - start_time > timeout:
                try:
                    proc.terminate()
                except Exception:
                    pass
                try:
                    proc.kill()
                except Exception:
                    pass
                break
            try:
                if not p.is_running() or p.status() == psutil.STATUS_ZOMBIE:
                    break
                cpu = p.cpu_percent(interval=0.1)
                cpu_usage += cpu
                mem_info = p.memory_info()
                rss = mem_info.rss
                if rss > last_rss:
                    mem_usage += rss - last_rss
                last_rss = rss
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                break
            if proc.poll() is not None:
                break
    finally:
        if proc.poll() is None:
            try:
                proc.terminate()
            except Exception:
                pass
            try:
                proc.kill()
            except Exception:
                pass
    return {'CPU Usage': cpu_usage, 'Memory Usage': mem_usage}

import subprocess
import os
import glob
ARCHIVE_DIR = '/tmp/archive'
def task_func(pattern):
    os.makedirs(ARCHIVE_DIR, exist_ok=True)
    files = glob.glob(pattern)
    base = os.path.basename(pattern)
    if not base or base == '*':
        base = 'archive'
    safe_base = base.replace('*', 'star').replace('?', 'q')
    archive_file = os.path.join(ARCHIVE_DIR, safe_base + '.tar.gz')
    if files:
        cmd = ['tar', '-czf', archive_file] + files
        result = subprocess.run(cmd)
        if result.returncode != 0:
            return archive_file
        for f in files:
            try:
                os.remove(f)
            except OSError:
                pass
    else:
        open(archive_file, 'ab').close()
    return archive_file

import subprocess
import pandas as pd
def task_func(script_path, output_file_path):
    result = subprocess.run(
        [script_path, output_file_path],
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE
    )
    if result.returncode != 0:
        raise ValueError(f"Script execution failed: {result.stderr.decode('utf-8', errors='ignore')}")
    try:
        df = pd.read_csv(output_file_path)
    except Exception as e:
        raise ValueError(f"Invalid CSV: {e}")
    if df.shape[1] != 2:
        raise ValueError("CSV must contain exactly 2 columns")
    cols = list(df.columns)
    ax = df.plot(kind="bar", x=cols[0], y=cols[1])
    return df, ax
